use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        RunInfo {
            date: utc_date(started),
            started,
        }
    }
}

/// Formats seconds since the Unix epoch as a UTC `YYYY-MM-DD` string.
///
/// The output is always exactly 10 characters. Because `started` is a `u64`,
/// the year is at least 1970. The year is clamped to 9999 so the 4-digit
/// field, and therefore the length contract, holds for any input.
fn utc_date(epoch_seconds: u64) -> String {
    let days = (epoch_seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9_999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

/// Howard Hinnant's `civil_from_days`: days since 1970-01-01 to (year, month, day).
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

export!(Node);
